function drawDuck(doc, layer, x, top, width, variant, theme) {
  variant = variant || "full";
  theme = theme || "light";
  if (!SqueakLogo.data[variant]) { throw new Error("drawDuck: unknown variant '" + variant + "' (use full, compact, silhouette, mono)"); }
  if (theme !== "dark" && theme !== "light") { throw new Error("drawDuck: unknown theme '" + theme + "' (use dark or light)"); }
  var layers = SqueakLogo.data[variant];
  var grp = layer.groupItems.add();
  grp.name = "Squeak duck / " + variant + (variant === "mono" ? " / " + theme : "");
  var li, si, L, rgb, item;
  for (li = 0; li < layers.length; li++) {
    L = layers[li];
    if (L.role === "mono") { rgb = (theme === "dark") ? SqueakLogo.colors.paper : SqueakLogo.colors.ink; }
    else { rgb = SqueakLogo.colors[L.role]; }
    if (L.subpaths.length === 1) {
      item = SqueakLogo._build(grp, L.subpaths[0], x, top, width);
      item.name = L.role;
      SqueakLogo._fill(item, rgb);
    } else {
      var cp = grp.compoundPathItems.add();
      for (si = 0; si < L.subpaths.length; si++) {
        item = SqueakLogo._build(cp, L.subpaths[si], x, top, width);
      }
      SqueakLogo._fill(cp.pathItems[0], rgb);
      cp.name = L.role;
    }
  }
  return grp;
}
